// Items de AMBAS lecturas llegan via $input.all()
// BLOGS_SITES_CONFIG: tiene ID_BLOG pero NO tiene STATUS (ni el campo)
// CONTENT_PIPELINE: tiene STATUS (campo presente aunque esté vacío)
const allItems = $input.all().map(i => i.json);
const allBlogs = allItems.filter(i => i.ID_BLOG && !('STATUS' in i));
const existingRows = allItems.filter(i => 'STATUS' in i);

if (allBlogs.length === 0) {
  return [{ json: { _skip: true, reason: 'No blogs en BLOGS_SITES_CONFIG' } }];
}

// SOLO contar backlog ÚTIL — ignorar basura completamente
const VALID_STATUSES = new Set(['PENDING', 'QUEUED', 'CONTENT_READY', 'READY']);
const JUNK_STATUSES = new Set(['FAILED', 'LOCK_TIMEOUT', 'ERROR', 'CANCELLED']);

const validRows = existingRows.filter(r =>
  VALID_STATUSES.has(String(r.STATUS ?? '').toUpperCase().trim())
);
const junkRows = existingRows.filter(r =>
  JUNK_STATUSES.has(String(r.STATUS ?? '').toUpperCase().trim())
);
const publishedRows = existingRows.filter(r =>
  String(r.STATUS ?? '').toUpperCase().trim() === 'PUBLISHED'
);
const archivedRows = existingRows.filter(r =>
  String(r.STATUS ?? '').toUpperCase().trim() === 'ARCHIVED'
);
const otherRows = existingRows.length - validRows.length - junkRows.length - publishedRows.length - archivedRows.length;

console.log('=== WF25 TITLE FACTORY - DIAGNÓSTICO ===');
console.log('Total filas pipeline: ' + existingRows.length);
console.log('  ✓ BACKLOG ÚTIL (PENDING/QUEUED/READY): ' + validRows.length);
console.log('  ✓ PUBLICADOS: ' + publishedRows.length);
console.log('  ✗ BASURA ignorada (FAILED/ERROR/etc): ' + junkRows.length);
console.log('  ~ ARCHIVADOS: ' + archivedRows.length);
console.log('  ? OTROS/VACÍOS: ' + otherRows);
console.log('Blogs configurados: ' + allBlogs.length);

// Anti-canibalización: SOLO de títulos válidos
const existingTitles = new Set(
  validRows.filter(r => r.TEMA_ARTICULO).map(r => r.TEMA_ARTICULO.toLowerCase().trim())
);

// Backlog VÁLIDO por blog
const validByBlog = {};
validRows.forEach(r => {
  const id = String(r.ID_BLOG || '').trim();
  if (id) validByBlog[id] = (validByBlog[id] || 0) + 1;
});

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');

const HIGH_RPM = ['abogad','impuest','legal','segur','accidente','multa','bienes','hipotec','salud','médic','insurance','lawyer','tax','accident'];
const isHighRpm = (nicho) => HIGH_RPM.some(k => (nicho || '').toLowerCase().includes(k));

// Umbral: generar si backlog útil < 1000 por blog
const PENDING_THRESHOLD = 1000;
const MAX_BLOGS_PER_RUN = 10;
const TITLES_PER_BLOG = 50;

const validBlogs = allBlogs.filter(b => b.ID_BLOG);
const blogsNeedingTitles = validBlogs
  .filter(b => (validByBlog[b.ID_BLOG] || 0) < PENDING_THRESHOLD)
  .sort((a, b) => {
    const aRpm = isHighRpm(a.NICHO) ? 0 : 1;
    const bRpm = isHighRpm(b.NICHO) ? 0 : 1;
    if (aRpm !== bRpm) return aRpm - bRpm;
    return (validByBlog[a.ID_BLOG] || 0) - (validByBlog[b.ID_BLOG] || 0);
  })
  .slice(0, MAX_BLOGS_PER_RUN);

if (blogsNeedingTitles.length === 0) {
  console.log('SKIP: todos los blogs tienen >= ' + PENDING_THRESHOLD + ' backlog válido. FAILED no cuenta.');
  return [{ json: {
    _skip: true,
    reason: 'Backlog útil suficiente en todos los blogs (FAILED ignorado)',
    diagnostico: {
      totalPipeline: existingRows.length,
      backlogUtil: validRows.length,
      publicados: publishedRows.length,
      basuraIgnorada: junkRows.length
    }
  }}];
}

console.log('Blogs que necesitan títulos nuevos (backlog útil < ' + PENDING_THRESHOLD + '):');
blogsNeedingTitles.forEach(b => {
  const vb = validByBlog[b.ID_BLOG] || 0;
  const rpm = isHighRpm(b.NICHO) ? ' [HIGH-RPM]' : '';
  console.log('  → ' + (b.SITIO_URL || b.ID_BLOG) + ' [' + (b.NICHO || 'general') + '] útil=' + vb + rpm);
});

return blogsNeedingTitles.map((blog) => ({
  json: {
    blogId: blog.ID_BLOG,
    sitioUrl: blog.SITIO_URL || '',
    nicho: blog.NICHO || 'general',
    idioma: blog.IDIOMA || 'es',
    bloggerId: blog.BLOGGER_ID || '',
    isHighRpm: isHighRpm(blog.NICHO),
    existingTitles: Array.from(existingTitles).slice(0, 50),
    titlesPerBlog: TITLES_PER_BLOG,
    dateStr,
    validBacklog: validByBlog[blog.ID_BLOG] || 0,
    diagnostico: {
      totalPipeline: existingRows.length,
      backlogUtil: validRows.length,
      publicados: publishedRows.length,
      basuraIgnorada: junkRows.length
    }
  }
}));

