const res = $('Generar Títulos DeepSeek').item.json;
const prev = $('Preparar por Blog').item.json;

if (!res.choices || !res.choices[0]) {
  throw new Error('DeepSeek sin respuesta válida: ' + JSON.stringify(res).substring(0, 300));
}

let titlesData;
try {
  const content = res.choices[0].message.content;
  const clean = content
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
  titlesData = JSON.parse(clean);
} catch(e) {
  throw new Error('JSON inválido de DeepSeek: ' + e.message + ' | Raw: ' + (res.choices[0].message.content || '').substring(0, 200));
}

const titles = titlesData.titles || [];
if (titles.length === 0) throw new Error('DeepSeek retornó lista vacía de títulos');

const existingSet = new Set((prev.existingTitles || []).map(t => t.toLowerCase().trim()));
const dateStr = prev.dateStr;

const rows = [];
for (const t of titles) {
  const titleLower = (t.title || '').toLowerCase().trim();
  if (!t.title || titleLower.length < 10) continue;
  if (existingSet.has(titleLower)) continue;
  existingSet.add(titleLower);
  const uid = 'TF' + dateStr + '-' + String(prev.blogId).substring(0, 6).replace(/[^a-z0-9]/gi, '') + '-' + Date.now().toString(36).slice(-4) + '-' + Math.random().toString(36).slice(2, 5);
  rows.push({
    ID_UNICO: uid,
    STATUS: 'PENDING',
    LOCK: 'FALSE',
    ID_BLOG: prev.blogId,
    KEYWORD: t.keywords || t.title.split(' ').slice(0, 4).join(' '),
    TEMA_ARTICULO: t.title,
    ID_PARENT_SILO: '',
    PRIORITY: String(t.priority || 2),
    RETRY_COUNT: '0'
  });
}

if (rows.length === 0) throw new Error('Todos los títulos generados ya existen en el pipeline');

console.log('=== TÍTULOS GENERADOS ===');
console.log('Blog: ' + prev.blogId + ' (' + prev.nicho + ')');
console.log('Generados por DeepSeek: ' + titles.length);
console.log('Nuevos únicos: ' + rows.length);
console.log('Duplicados descartados: ' + (titles.length - rows.length));
console.log('Backlog útil antes: ' + prev.validBacklog);
console.log('Backlog estimado post-inserción: ' + (prev.validBacklog + rows.length));
console.log('Diagnóstico pipeline: ' + JSON.stringify(prev.diagnostico));

return rows.map(r => ({ json: r }));

// Recibe SOLO filas de CONTENT_PIPELINE
// Identifica FAILED/LOCK_TIMEOUT con RETRY_COUNT > 2 para archivar
const allItems = $input.all().map(i => i.json);

const toArchive = allItems.filter(r => {
  const status = String(r.STATUS ?? '').toUpperCase().trim();
  const retry = parseInt(String(r.RETRY_COUNT || '0'), 10);
  return (status === 'FAILED' || status === 'LOCK_TIMEOUT') && retry > 2 && r.ID_UNICO;
});

if (toArchive.length === 0) {
  console.log('Limpieza: no hay huérfanos para archivar.');
  return [{ json: { _noArchive: true } }];
}

console.log('Limpieza automática: archivando ' + toArchive.length + ' registros FAILED/LOCK_TIMEOUT con RETRY_COUNT > 2');
toArchive.slice(0, 5).forEach(r => {
  console.log('  → ' + r.ID_UNICO + ' [' + r.STATUS + '] retry=' + r.RETRY_COUNT);
});
if (toArchive.length > 5) console.log('  ... y ' + (toArchive.length - 5) + ' más');

return toArchive.map(r => ({
  json: {
    ID_UNICO: r.ID_UNICO,
    STATUS: 'ARCHIVED'
  }
}));
